package com.rekluzlabs.makokolorize.domaindata class RunConfig(    val ddcolorInputSize: Int = 512,    val vibrancy: Float = 1.0f,    val upscalingEnabled: Boolean = false,    val faceRestoreEnabled: Boolean = false,    val denoisingEnabled: Boolean = false,    val colorizeEnabled: Boolean = true,    val codeFormerFidelity: Float = 0.9f,    val scunetStrength: Float = 1.0f,    val scunetAdvancedNoiseRemoval: Boolean = false,    val upscaleScale: Int = 2) {    fun withFullRestore() = copy(        denoisingEnabled = true,        colorizeEnabled = true,        upscalingEnabled = true,        faceRestoreEnabled = true,        scunetStrength = 1.0f,        vibrancy = 1.0f,        codeFormerFidelity = 0.9f,        scunetAdvancedNoiseRemoval = false,        upscaleScale = 2    )    fun withColorizeOnly() = copy(        denoisingEnabled = false,        colorizeEnabled = true,        upscalingEnabled = false,        faceRestoreEnabled = false,        vibrancy = 1.0f,        ddcolorInputSize = 512    )    fun withUpscaleOnly() = copy(        denoisingEnabled = false,        colorizeEnabled = false,        upscalingEnabled = true,        faceRestoreEnabled = false,        upscaleScale = 2    )    fun withDefaults() = RunConfig()}